Write a python function that takes a file path to a CSV file and a list of column names and returns a dictionary where the keys are the column names and the values are the maximum values in the corresponding columns. The function should handle any number of columns and rows.
Problem: import csv

def max_values(file_path, columns):
    with open(file_path, 'r') as file:
        reader = csv.DictReader(file)
        max_values = {column: float('-inf') for column in columns}

        for row in reader:
            for column in columns:
                value = float(row[column])
                if value > max_values[column]:
                    max_values[column] = value

    return max_values

```python
import csv

def max_values(file_path, columns):
    with open(file_path, 'r') as file:
        reader = csv.DictReader(file)
        max_values = {column: float('-inf') for column in columns}

        for row in reader:
            for column in columns:
                value = float(row[column])
                if value > max_values[column]:
                    max_values[column] = value

    return max_values
```

